CREATE TABLE liquidaciones.generated_documents(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,batch_id uuid NOT NULL REFERENCES liquidaciones.liquidation_batches(batch_id),remittance_id bigint NOT NULL,recipient_member_id bigint NOT NULL,document_type text NOT NULL,file_path text NOT NULL,status text NOT NULL,generated_at timestamptz,error_message text,generation_attempt integer NOT NULL DEFAULT 1,file_hash varchar(64),created_by text,benchmark_source_fingerprint varchar(64));
CREATE TABLE liquidaciones.exported_draft_documents(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,remittance_id bigint,recipient_member_id bigint,member_name text NOT NULL DEFAULT '',campaign text NOT NULL,crop text NOT NULL,remittance_name text NOT NULL DEFAULT '',file_path text NOT NULL,status text NOT NULL DEFAULT 'GENERATED',generated_at timestamptz NOT NULL,source text NOT NULL DEFAULT 'MANUAL_DRAFT_EXPORT',company text NOT NULL DEFAULT '',file_hash varchar(64));
CREATE TABLE liquidaciones.liquidation_document_snapshots(batch_id uuid NOT NULL REFERENCES liquidaciones.liquidation_batches(batch_id),recipient_member_id bigint NOT NULL,payload_json jsonb NOT NULL,schema_version integer NOT NULL,calculation_fingerprint varchar(64) NOT NULL,created_at timestamptz NOT NULL,created_by text,PRIMARY KEY(batch_id,recipient_member_id));
